export interface ParentCategory {
  id: string;
  name: string;
  slug: string;
  description: string;
  icon?: string;
}

export interface SubCategory {
  id: string;
  name: string;
  slug: string;
  parentCategoryId: string;
  description: string;
}

export interface CalculatorSEO {
  title: string;
  description: string;
  keywords: string[];
}

export interface BreadcrumbItem {
  label: string;
  href: string;
}

export interface Calculator {
  id: string;
  name: string;
  slug: string;
  href: string;
  parentCategoryId: string;
  subCategoryId: string;
  categoryPath: string[];
  icon: string;
  description: string;
  shortDescription?: string;
  featured?: boolean;
  popular?: boolean;
  calculatorType?: string;
  complexity?: "simple" | "advanced";
  searchKeywords?: string[];
  schemaType?: string;
  seo: CalculatorSEO;
  relatedCalculators?: string[];
}

