export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export function getCalculatorBySlug(slug: string): Calculator | undefined {
  return CALCULATORS.find((c) => c.slug === slug);
}

export function getCalculatorsByParentCategory(
  parentCategoryId: string,
): Calculator[] {
  return CALCULATORS.filter((c) => c.parentCategoryId === parentCategoryId);
}

export function getCalculatorsBySubCategory(
  subCategoryId: string,
): Calculator[] {
  return CALCULATORS.filter((c) => c.subCategoryId === subCategoryId);
}

export function getRelatedCalculators(
  calculatorOrSlug: Calculator | string,
  limit: number = 5,
): Calculator[] {
  const calculator =
    typeof calculatorOrSlug === "string"
      ? getCalculatorBySlug(calculatorOrSlug)
      : calculatorOrSlug;
  if (!calculator || !calculator.relatedCalculators) return [];
  return calculator.relatedCalculators
    .map((slug) => getCalculatorBySlug(slug))
    .filter((c): c is Calculator => c !== undefined)
    .slice(0, limit);
}

export function generateBreadcrumbs(calculator: Calculator): BreadcrumbItem[] {
  const crumbs: BreadcrumbItem[] = [{ label: "Home", href: "/" }];
  const parent = PARENT_CATEGORIES.find(
    (p) => p.id === calculator.parentCategoryId,
  );
  if (parent) {
    crumbs.push({
      label: parent.name,
      href: "/" + parent.slug,
    });
  }
  // Subcategory removed for shallower architecture
  crumbs.push({ label: calculator.name, href: calculator.href });
  return crumbs;
}
